const fs = require('fs');
const source = fs.readFileSync('src/auth-service.ts', 'utf8')
  .replace('export interface TokenClaims { subject: string; expiresAt: number; }\n', '')
  .replace('export class AuthService', 'class AuthService')
  .replace('(token: string): TokenClaims', '(token)')
  .replace('(token: string): string', '(token)');
eval(source + '\n globalThis.AuthService = AuthService;');
const auth = new AuthService();
for (const token of ['', 'expired']) {
  for (const method of ['validateToken', 'refreshToken']) {
    let rejected = false;
    try { auth[method](token); } catch { rejected = true; }
    if (!rejected) throw new Error(`${method} accepted ${JSON.stringify(token)}`);
  }
}
const claims = auth.validateToken('user-token');
if (claims.subject !== 'user-token' || typeof claims.expiresAt !== 'number' || claims.expiresAt <= Date.now()) throw new Error('invalid claims');
if (auth.refreshToken('user-token') !== 'user-token-refreshed') throw new Error('invalid refresh result');
console.log('AuthService behavioral checks passed');
